package com.inodra.movesui.project

import junit.framework.TestCase
import java.nio.file.Files

class MoveLockTest : TestCase() {
    fun `test parses pinned packages and maps git cache dirs`() {
        val lock = MoveLock.parse("""
            # Generated by move; do not edit
            [move]
            version = 4

            [pinned.mainnet.Sui]
            source = { git = "https://github.com/MystenLabs/sui.git", subdir = "crates/sui-framework/packages/sui-framework", rev = "b0535f1f" }
            use_environment = "mainnet"
            deps = { MoveStdlib = "MoveStdlib" }

            [pinned.mainnet.vaults]
            source = { git = "https://github.com/abyss/vaults.git", subdir = "packages/vaults", rev = "v1.2.0" }
            deps = {}

            [pinned.mainnet.counter]
            source = { root = true }
            deps = { std = "MoveStdlib", sui = "Sui", vaults = "vaults" }
        """.trimIndent())
        val pkgs = lock.packagesFor()
        assertEquals(listOf("Sui", "vaults", "counter"), pkgs.map { it.name })
        val sui = pkgs[0]
        assertEquals("crates/sui-framework/packages/sui-framework", sui.subdir)
        assertEquals("b0535f1f", sui.rev)
        assertTrue(pkgs[2].isRoot)
        assertEquals(mapOf("std" to "MoveStdlib", "sui" to "Sui", "vaults" to "vaults"), pkgs[2].deps)

        val cache = Files.createTempDirectory("move-cache")
        val exact = Files.createDirectory(cache.resolve("https___github_com_MystenLabs_sui_git_b0535f1f"))
        Files.createDirectory(cache.resolve("https___github_com_MystenLabs_sui_git_deadbeef"))
        assertEquals(exact, MoveLock.gitCacheDir(sui.git!!, sui.rev!!, cache))
        // Branch pins fall back to any checkout of that repository.
        assertNotNull(MoveLock.gitCacheDir(sui.git!!, "framework/testnet", cache))
        assertNull(MoveLock.gitCacheDir("https://example.com/none.git", "x", cache))
    }
}
